  const remPz = await prisma.eduReminder.findMany({ where: { tenantId: T, dedupeKey: { startsWith: `jur:prazo:${pz.json.id}:` } } })
  check('prazo fatal em 2 dias gera lembrete crítico', remPz.length >= 1 && remPz.every((r) => r.severity === 'CRITICO'), remPz)
  const pz2 = await call(legal, 'POST', `${J}/processos/${pr1.json.id}/prazos`, { titulo: 'Manifestação sobre laudo', dataFatal: day(40), fatal: false })
