  check('lista global de prazos até 7 dias', (await call(legal, 'GET', `${J}/prazos?status=ABERTO&ateDias=7`)).json?.items?.every((p: any) => p.alerta.dias <= 7))
  check('perdido exige observação (400)', (await call(legal, 'POST', `${J}/prazos/${pz2.json.id}/perdido`, {})).status === 400)
  check('cumprir prazo', (await call(legal, 'POST', `${J}/prazos/${pz.json.id}/cumprir`, { observacao: 'Protocolado' })).json?.status === 'CUMPRIDO')
