  check('realizar audiência exige resultado (400)', (await call(legal, 'POST', `${J}/audiencias/${au.json.id}/realizar`, {})).status === 400)
  check('secretaria vê agenda de audiências (200)', (await call(sec, 'GET', `${J}/audiencias?ateDias=30`)).status === 200)
  check('secretaria não agenda audiência (403)', (await call(sec, 'POST', `${J}/processos/${pr1.json.id}/audiencias`, { dataHora: day(5) })).status === 403)
  check('agenda de prazos não vaza criminal para secretaria', await (async () => { await call(legal, 'POST', `${J}/processos/${crim.json.id}/prazos`, { titulo: 'Resposta à autoridade', dataFatal: day(3) }); return !(await call(sec, 'GET', `${J}/prazos?ateDias=30`)).json?.items?.some((p: any) => p.processoId === crim.json.id) })())
  check('sub-recurso de outro tenant não pode ser alterado (404)', (await call(legal2, 'PUT', `${J}/prazos/${pz2.json.id}`, { titulo: 'Invadido por B' })).status === 404)
