  check('encerrar cancela prazos abertos e audiências', (await prisma.jurPrazo.count({ where: { processoId: pr1.json.id, status: 'ABERTO' } })) === 0 && (await prisma.jurAudiencia.count({ where: { processoId: pr1.json.id, status: 'AGENDADA' } })) === 0)
  check('baixa da provisão registrada no histórico', (await prisma.jurProvisaoHist.count({ where: { processoId: pr1.json.id, valor: 0 } })) >= 1)
